class Solution {
    public int reverseBits(int n) {
        int reversed = 0;
        for (int bitIndex = 0; bitIndex < 32; bitIndex++) {
            reversed = (reversed << 1) | (n & 1);
            n >>>= 1;
        }
        return reversed;
    }
}
